cd /private/var/folders/qj/j67my3_j6bzb4y5t82bvmkfh0000gn/T/m5-o-fbektazt/catalogue/work/exports
python3 - <<'E'
import json,csv,collections
prod={}
for l in open('shopify/products.jsonl'):
    d=json.loads(l)
    if 'sku' in d: prod[d['sku']]=d
byupc={d['barcode']:s for s,d in prod.items()}
inv=list(csv.DictReader(open('3pl/inventory_snapshot.csv')))
used={r['Client SKU'] for r in inv}
print('shopify skus w/o 3pl sku:',[s for s in prod if s not in used])
for r in inv:
    if r['Client SKU'] not in prod: print(r['Item Code'],repr(r['Client SKU']),r['Description'],r['UPC'],'->',byupc.get(r['UPC']))
print('upc matches',sum(1 for r in inv if byupc.get(r['UPC'])), 'upc blank',sum(1 for r in inv if not r['UPC']))
# amazon
inv=list(csv.DictReader(open('amazon/fba_inventory.txt'),delimiter='\t'))
for r in inv: print(r['sku'],r['fnsku'],r['asin'],r['afn-listing-exists'],r['mfn-listing-exists'])
E

