byM=collections.defaultdict(set); byA=collections.defaultdict(set)
for k,a in acc.items():
    for m in a['mail']: byM[m].add(k)
    for x in a['addr']: byA[x].add(k)
def addp(s,rule):
    s=sorted(s,key=lambda k:(acc[k]['first'],int(k)))
    for n in s[1:]: pairs.setdefault((s[0],n),set()).add(rule)
for m,v in byM.items():
    if len(v)>1: addp(v,'mail')
for x,v in byA.items():
    if len(v)>1: addp(v,'nameaddr')
print(len(pairs),collections.Counter(frozenset(r) for r in pairs.values()))
# mail-only: name overlap?
nov=0
for (o,n),r in pairs.items():
    if r=={'mail'} and not (acc[o]['name'] & acc[n]['name']): nov+=1
print('mail-only no name overlap',nov)
import random
random.seed(1)
for (o,n),r in random.sample([p for p in pairs.items() if p[1]=={'mail'}],10):
    print('MAIL',r,acc[o]['raw'],acc[o]['name'],'|',acc[n]['raw'],acc[n]['name'])
for (o,n),r in random.sample([p for p in pairs.items() if p[1]=={'nameaddr'}],10):
    print('NA',acc[o]['raw'],'|',acc[n]['raw'],acc[n]['name'])
# components
