    while par.setdefault(x,x)!=x: par[x]=par[par[x]]; x=par[x]
    return x
for o,n in pairs: par[f(n)]=f(o)
comp=collections.defaultdict(set)
for x in list(par): comp[f(x)].add(x)
print(collections.Counter(len(v) for v in comp.values()))
