        if d.get('barcode'):
            fs.append({"e": e, "a": "sku/upc", "v": d['barcode']})
        (exact if c == d['sku'] else norm).append(fs)
    tx([f for fs in exact for f in fs], 'shopify/products.jsonl', 1)
